#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

void insertFront(struct Node **headRef, int value) {
    struct Node *newNode = malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = *headRef;
    *headRef = newNode;
}

int main() {
    struct Node *head = NULL;
    insertFront(&head, 10);
    if (head == NULL) {
        printf("List is still empty\n");
    } else {
        printf("%d\n", head->data);
    }
    return 0;
}
